<?php
require_once __DIR__.'/../lib/app.php';$pageTitle='휴가현황 조회';include '_top.php';$pdo=db();[$scopeSql,$scopeParams]=request_scope_sql('e');$month=$_GET['month']??date('Y-m');$employeeId=(int)($_GET['employee_id']??0);$departmentId=(int)($_GET['department_id']??0);$from=$month.'-01';$to=date('Y-m-t',strtotime($from));$where=["lr.status IN ('in_approval','approved')",'lr.start_date<=?','lr.end_date>=?',$scopeSql];$params=[$to,$from,...$scopeParams];if($employeeId){$where[]='e.id=?';$params[]=$employeeId;}if($departmentId){$where[]='e.department_id=?';$params[]=$departmentId;}$sql="SELECT lr.*,e.name,e.position,e.id employee_id,d.name department_name,lt.name leave_name,lt.color FROM leave_requests lr JOIN employees e ON e.id=lr.employee_id LEFT JOIN departments d ON d.id=e.department_id JOIN leave_types lt ON lt.id=lr.leave_type_id WHERE ".implode(' AND ',$where)." ORDER BY lr.start_date,e.sort_order";$s=$pdo->prepare($sql);$s->execute($params);$rows=$s->fetchAll();$by=[];foreach($rows as $r)foreach(date_range(max($from,$r['start_date']),min($to,$r['end_date'])) as $date)$by[$date][]=$r;
$depSql='SELECT id,name FROM departments WHERE is_active=1';$depParams=[];if(!can_manage_hr()){$ids=accessible_department_ids();$depSql.=' AND id IN ('.implode(',',array_fill(0,count($ids),'?')).')';$depParams=$ids;}$depSql.=' ORDER BY sort_order,id';$s=$pdo->prepare($depSql);$s->execute($depParams);$deps=$s->fetchAll();$empSql="SELECT e.id,e.name,e.position FROM employees e WHERE e.is_active=1 AND $scopeSql ORDER BY e.sort_order,e.id";$s=$pdo->prepare($empSql);$s->execute($scopeParams);$employees=$s->fetchAll();
?><div class="page-title-row"><div><h1>직원별·일자별 휴가현황</h1><p class="page-desc">월·부서·직원별로 승인 및 결재중인 휴가 일정을 조회합니다.</p></div></div><form class="filter-bar" method="get"><label>조회월<input type="month" name="month" value="<?=h($month)?>"></label><label>부서<select name="department_id"><option value="0">전체</option><?php foreach($deps as $d):?><option value="<?=$d['id']?>" <?=$departmentId===$d['id']?'selected':''?>><?=h($d['name'])?></option><?php endforeach?></select></label><label>직원<select name="employee_id"><option value="0">전체</option><?php foreach($employees as $e):?><option value="<?=$e['id']?>" <?=$employeeId===$e['id']?'selected':''?>><?=h($e['name'].' '.$e['position'])?></option><?php endforeach?></select></label><button class="btn">조회</button></form><div class="status-layout"><section class="card"><h2>일자별 현황</h2><?php foreach(date_range($from,$to) as $date):$items=$by[$date]??[];if(!$items)continue;?><div class="calendar-day"><strong><?=h($date)?> (<?=['일','월','화','수','목','금','토'][date('w',strtotime($date))]?>)</strong><?php foreach($items as $r):?><div><span style="color:<?=h($r['color'])?>">●</span> <a class="text-link" href="?month=<?=h($month)?>&employee_id=<?=$r['employee_id']?>"><?=h($r['name'].' '.$r['position'])?></a> · <?=h($r['department_name'])?> · <?=h($r['leave_name'])?> <span class="badge"><?=h($r['status']==='approved'?'승인':'결재중')?></span></div><?php endforeach?></div><?php endforeach?><?php if(!$rows):?><p class="muted">조회된 휴가일정이 없습니다.</p><?php endif?></section><section class="card"><h2>신청 상세</h2><div class="table-wrap"><table class="table"><tr><th>직원</th><th>부서</th><th>유형</th><th>기간</th><th>일수</th><th>상태</th></tr><?php foreach($rows as $r):?><tr><td><?=h($r['name'].' '.$r['position'])?></td><td><?=h($r['department_name'])?></td><td><?=h($r['leave_name'])?></td><td><?=h($r['start_date'])?> ~ <?=h($r['end_date'])?></td><td><?=fmt_days($r['requested_days'])?></td><td><?=h($r['status'])?></td></tr><?php endforeach?></table></div></section></div><?php include '_bottom.php';?>